import ssl

# Try to get Max Volmer Wikipedia page
def get_wikipedia_page(title):
    url = f"https://en.wikipedia.org/api/rest_v1/page/html/{title}"
    context = ssl.create_default_context()
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE

    req = urllib.request.Request(url, headers={
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
    })

    try:
        with urllib.request.urlopen(req, context=context, timeout=10) as response:
            html = response.read().decode('utf-8')
            return html
    except Exception as e:
        print(f"Error fetching {title}: {e}")
        return None

# Try to get Otto Hahn page
html_hahn = get_wikipedia_page("Otto_Hahn")
if html_hahn:
    if "Volmer" in html_hahn:
        print("Max Volmer mentioned in Otto Hahn's Wikipedia page!")
        # Find the context
        idx = html_hahn.find("Volmer")
        start = max(0, idx - 200)
        end = min(len(html_hahn), idx + 200)
        print(f"Context: {html_hahn[start:end]}")
    else:
        print("Max Volmer NOT mentioned in Otto Hahn's Wikipedia page.")
else:
    print("Could not fetch Otto Hahn page")
